import {Engine} from './engine.js';
import {Tuner} from './tuner.js';
import * as DB from './storage.js';
import {id,newProject,time,gain,globalRate,duration,instruments,noteName,tunerReading} from './music.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=$('#app'),modal=$('#modal'),body=$('#dialogBody'),engine=new Engine(),tuner=new Tuner();
let projects=[],p=null,page='playback',screen='projects',loading=false,importTarget=null,noticeTimer,taps=[],tunerPrefs=JSON.parse(localStorage.getItem('tuner')||'{"instrument":1,"tuning":0,"string":-1,"a4":440}');
function notify(s){$('#notice').textContent=s;$('#notice').hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').hidden=true,6500);}
function fail(e){console.error(e);notify(e.message||'Não foi possível concluir. Tente novamente.');}
function listen(selector,event,handler){document.querySelectorAll(selector).forEach(el=>el.addEventListener(event,e=>Promise.resolve(handler(e,el)).catch(fail)));}
function button(text,action,cls=''){return `<button data-action="${action}" class="${cls}">${text}</button>`;}
function head(title){return `<div class="modal-head"><h2>${title}</h2><button data-close>Fechar</button></div>`;}
function show(html,drawer=false){modal.className=drawer?'drawer':'';body.innerHTML=html;body.querySelectorAll('[data-close]').forEach(el=>el.onclick=()=>modal.close());if(!modal.open)modal.showModal();}
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
function persist(){if(p)DB.saveProject(p).catch(e=>{console.error(e);notify('Não foi possível salvar: o armazenamento pode estar cheio. Exporte um backup.');});}
engine.onPrepare=s=>notify('Preparando áudio · '+s);
engine.onInterrupted=()=>{notify('Reprodução pausada pelo navegador. Toque em Play para continuar.');render();};
async function choose(project){if(loading)return;loading=true;tuner.stop();screen='projects';p=project;render();try{await engine.load(p,notify);}catch(e){fail(e);}finally{loading=false;render();}}
function render(){if(screen==='tuner'){renderTuner();return;}if(screen==='support'){renderSupport();return;}if(screen==='help'){renderHelp();return;}const playing=engine.playing;
  app.innerHTML=`<div class="row between"><div><div class="section-title">SUA BIBLIOTECA</div><h1>Projetos</h1></div><div class="row"><button id="restore" class="backup">Importar backup</button>${p?'<button id="backup" class="backup">Exportar backup</button>':''}</div></div>
  ${p?`<section class="transport" aria-label="Transporte"><button id="previous" aria-label="Voltar ao início">Ⅰ◀</button><button id="play" class="primary play" ${loading||!engine.ready?'disabled':''}>${playing?'Ⅱ Pausar':'▶ Play'}</button><button id="stop" aria-label="Parar">■</button><button id="next" aria-label="Próximo projeto">▶Ⅰ</button><span class="clock" id="clock">${time(engine.current())} / ${time(duration(p))}</span><span class="spacer"></span><span class="tempo">${(p.bpm*globalRate(p)).toFixed(1)} BPM · ${p.meter}/4</span></section>`:''}
  <div class="cards">${projects.map(x=>`<button class="project ${x===p?'selected':''}" data-project="${x.id}">${x.art?`<img src="${esc(x.art)}" alt="">`:''}<strong>${esc(x.name)}</strong><small>${esc(x.key||'Sem tom')} · ${x.bpm} BPM · ${x.tracks.length} tracks</small></button>`).join('')}<button class="project" id="new">＋ Novo projeto</button></div>
  ${!p?`<section class="panel empty"><img src="assets/logo.png" alt=""><h1>Sua música. Seu controle.</h1><p>Importe as tracks de uma música e prepare sua mixagem.</p><button class="primary" id="emptyImport">Importar tracks</button><p class="footer">Projetos e áudios ficam neste navegador. Exporte backups para transferir ou guardar uma cópia.</p></section>`:`<div class="row between"><div><h2>${esc(p.name)}</h2><p>${p.tracks.length} tracks · ${loading?'Preparando áudio…':'Áudio local'} ${engine.bytes?'· '+Math.round(engine.bytes/1048576)+' MB em memória':''}</p></div><button id="edit">Editar projeto</button></div>
  <nav class="tabs"><button id="playbackTab" class="${page==='playback'?'active':''}">Playback</button><button id="mixerTab" class="${page==='mixer'?'active':''}">Mixer</button></nav>
  ${page==='playback'?`<section class="panel"><div class="row between"><span class="section-title">TIMELINE</span><small>Toque para navegar</small></div><canvas class="wave" id="wave" aria-label="Timeline da música"></canvas><div class="sections">${p.markers.map(m=>`<button data-marker="${m.id}" class="${m.id===p.selectedMarker?'active':''}" title="Segure para selecionar loop">${esc(m.name)}</button>`).join('')}</div></section>`:''}
  <div class="tools"><button id="loop" class="${p.loop?'active':''}">↻ Loop</button><button id="sections">＋ Seção</button><button id="metronome">Metrônomo</button><button id="pitch" class="dsp ${p.pitch?'active':''}">TOM<b>${p.pitch?`${p.pitch>0?'+':''}${p.pitch}`:'Original'}</b></button><button id="speed" class="dsp ${p.speed!==100?'active':''}">VELOCIDADE<b>${p.speed}%</b></button></div>
  ${page==='mixer'?'<div class="row group"><button id="groups">DCA / BUS</button><button id="routing">Routing / Stereo split</button></div>':''}<div class="row between"><span class="section-title">MIXER</span><small id="playState">${playing?'REPRODUZINDO':loading?'PREPARANDO':'PRONTO'}</small></div>
  <section class="strips" aria-label="Canais do mixer">${p.tracks.map(t=>strip(t)).join('')}${strip({id:'master',name:'MASTER',db:p.master,mute:p.masterMute},true)}</section><p class="footer">Projetos salvos neste navegador. Faça backup antes de limpar os dados do site. ${engine.bytes>200*1048576?'Projeto grande: monitore a memória do aparelho.':''}</p>`}`;
  listen('[data-project]','click',(_,el)=>choose(projects.find(x=>x.id===el.dataset.project)));
  $('#new').onclick=()=>startImport(null);$('#restore').onclick=()=>$('#backupFile').click();if($('#emptyImport'))$('#emptyImport').onclick=()=>startImport(null);if(!p)return;
  $('#backup').onclick=()=>DB.exportProject(p).then(()=>notify('Backup exportado.')).catch(fail);$('#play').onclick=async()=>{try{if(engine.playing)engine.pause();else{notify('Preparando reprodução…');await engine.play();}render();}catch(e){fail(e);}};
  $('#stop').onclick=()=>{engine.stop();render();};$('#previous').onclick=()=>engine.seek(0).catch(fail);$('#next').onclick=()=>choose(projects[(projects.indexOf(p)+1)%projects.length]);$('#edit').onclick=editProject;
  $('#playbackTab').onclick=()=>{page='playback';render();};$('#mixerTab').onclick=()=>{page='mixer';render();};$('#loop').onclick=async()=>{p.loop=!p.loop;persist();await engine.rebuild();render();};$('#sections').onclick=sections;$('#metronome').onclick=metronome;$('#pitch').onclick=()=>dsp('pitch');$('#speed').onclick=()=>dsp('speed');if($('#groups'))$('#groups').onclick=groups;if($('#routing'))$('#routing').onclick=routing;
  bindStrips();bindMarkers();const wave=$('#wave');if(wave){wave.onpointerdown=e=>{const r=wave.getBoundingClientRect();engine.seek((e.clientX-r.left)/r.width*duration(p)).catch(fail);};drawWave();}
}
function strip(t,master=false){return `<article class="strip ${master?'master':''}" data-strip="${t.id}"><div class="name" ${master?'':'draggable="true"'}>${esc(t.name)}</div>${master?'<small>OUT 1 / 2</small><div style="height:28px"></div>':`<small>Pan · <span id="pan-${t.id}">${t.pan===0?'C':t.pan<0?'L':'R'}</span></small><input data-pan="${t.id}" aria-label="Pan ${esc(t.name)}" type="range" min="-1" max="1" step=".01" value="${t.pan}">`}<div class="sm">${master?'':`<button data-solo="${t.id}" class="${t.solo?'active':''}" aria-label="Solo ${esc(t.name)}">S</button>`}<button data-mute="${t.id}" class="${t.mute?'active':''}" aria-label="Mute ${esc(t.name)}">M</button></div><button class="zero" data-db="${t.id}">${t.db<=-60?'−∞':t.db.toFixed(1)} dB</button><div class="fader-area"><div class="scale">${['+10','0','−10','−20','−40','−∞'].map(x=>`<span>${x}</span>`).join('')}</div><input class="fader" data-fader="${t.id}" type="range" min="0" max="1000" step="1" value="${dbToFader(t.db)}" aria-label="Volume ${esc(t.name)}"><div class="meter"><i id="meter-${t.id}"></i></div></div><button data-zero="${t.id}">0dB</button>${master?'<small>MASTER</small>':''}</article>`;}
function dbToFader(db){return db>=0?800+db*20:db>=-20?800+db*20:db>=-40?400+(db+20)*15:100+(db+40)*5;}
function faderToDb(v){return v>=800?(v-800)/20:v>=400?(v-800)/20:v>=100?-20+(v-400)/15:-40+(v-100)/5;}
function setDb(track,value){const db=Math.max(-60,Math.min(10,value));if(track==='master')p.master=db;else p.tracks.find(t=>t.id===track).db=db;engine.updateMix();persist();const f=$(`[data-fader="${track}"]`),b=$(`[data-db="${track}"]`);if(f)f.value=dbToFader(db);if(b)b.textContent=db<=-60?'−∞ dB':db.toFixed(1)+' dB';}
function bindStrips(){listen('[data-fader]','input',(_,el)=>setDb(el.dataset.fader,faderToDb(+el.value)));listen('[data-zero]','click',(_,el)=>setDb(el.dataset.zero,0));listen('[data-fader]','dblclick',(_,el)=>setDb(el.dataset.fader,0));listen('[data-db]','click',(_,el)=>{const v=prompt('Volume em dB (−60 a +10)',parseFloat(el.textContent)||0);if(v!==null&&Number.isFinite(Number(v.replace(',','.'))))setDb(el.dataset.db,Number(v.replace(',','.')));});listen('[data-pan]','input',(_,el)=>{p.tracks.find(t=>t.id===el.dataset.pan).pan=+el.value;engine.updateMix();persist();$(`#pan-${el.dataset.pan}`).textContent=+el.value===0?'C':+el.value<0?'L':'R';});listen('[data-solo],[data-mute]','click',(_,el)=>{const key=el.dataset.solo?'solo':'mute',tid=el.dataset.solo||el.dataset.mute;if(tid==='master')p.masterMute=!p.masterMute;else{const t=p.tracks.find(t=>t.id===tid);t[key]=!t[key];}engine.updateMix();persist();el.classList.toggle('active');});
  let dragged;listen('.name[draggable]','dragstart',(e,el)=>{dragged=el.parentElement.dataset.strip;e.dataTransfer.setData('text/plain',dragged);e.dataTransfer.setDragImage(el.parentElement,60,30);el.parentElement.classList.add('dragging');});listen('.strip','dragover',e=>e.preventDefault());listen('.strip','drop',(e,el)=>{e.preventDefault();reorder(dragged,el.dataset.strip);});listen('.name','dragend',()=>document.querySelectorAll('.dragging').forEach(x=>x.classList.remove('dragging')));
  // Pointer drag uses the full card as a floating preview on touch devices.
  listen('.name[draggable]','pointerdown',(e,el)=>{if(e.pointerType==='mouse')return;const card=el.parentElement;let ghost=null,timer=setTimeout(()=>{ghost=card.cloneNode(true);ghost.removeAttribute('data-strip');ghost.style.cssText=`position:fixed;z-index:20;pointer-events:none;width:${card.offsetWidth}px;opacity:.8;left:${e.clientX-60}px;top:${e.clientY-30}px`;document.body.append(ghost);},300);const move=ev=>{if(ghost){ev.preventDefault();ghost.style.left=(ev.clientX-60)+'px';ghost.style.top=(ev.clientY-30)+'px';}};const end=ev=>{clearTimeout(timer);if(ghost){const target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-strip]');ghost.remove();if(target)reorder(card.dataset.strip,target.dataset.strip);}window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end);window.removeEventListener('pointercancel',end);};window.addEventListener('pointermove',move,{passive:false});window.addEventListener('pointerup',end);window.addEventListener('pointercancel',end);});}
function reorder(a,b){const i=p.tracks.findIndex(t=>t.id===a),j=p.tracks.findIndex(t=>t.id===b);if(i<0||j<0||i===j)return;p.tracks.splice(j,0,p.tracks.splice(i,1)[0]);persist();render();}
function bindMarkers(){listen('[data-marker]','pointerdown',(_,el)=>{let held=false;const timer=setTimeout(async()=>{held=true;p.selectedMarker=el.dataset.marker;persist();await engine.rebuild();render();},450);const end=()=>{clearTimeout(timer);if(!held){const m=p.markers.find(m=>m.id===el.dataset.marker);engine.seek(m.start/globalRate(p)).catch(fail);}el.removeEventListener('pointerup',end);};el.addEventListener('pointerup',end,{once:true});el.addEventListener('pointercancel',()=>clearTimeout(timer),{once:true});});}
function drawWave(){const canvas=$('#wave');if(!canvas||!p)return;const r=canvas.getBoundingClientRect(),dpr=devicePixelRatio||1;canvas.width=r.width*dpr;canvas.height=r.height*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);const peaks=p.tracks[0]?.peaks||[];c.strokeStyle='#8198bb';c.lineWidth=1;for(let i=0;i<peaks.length;i++){const x=i/peaks.length*r.width,y=peaks[i]*r.height*.43;c.beginPath();c.moveTo(x,r.height/2-y);c.lineTo(x,r.height/2+y);c.stroke();}const pos=engine.current()/Math.max(.01,duration(p))*r.width;c.strokeStyle='#387bff';c.lineWidth=2;c.beginPath();c.moveTo(pos,0);c.lineTo(pos,r.height);c.stroke();}
function startImport(target){if(loading)return;importTarget=target;$('#files').click();}
$('#import').onclick=()=>{if(p){show(head('Importar tracks')+`<div class="stack"><button id="addHere">Adicionar a ${esc(p.name)}</button><button id="addNew">Criar novo projeto</button></div>`);$('#addHere').onclick=()=>{modal.close();startImport(p);};$('#addNew').onclick=()=>{modal.close();startImport(null);};}else startImport(null);};
$('#files').onchange=async e=>{const files=[...e.target.files];e.target.value='';if(!files.length)return;engine.pause();loading=true;const project=importTarget||newProject(files[0].name.replace(/\.[^.]+$/,''));if(!importTarget)projects.push(project);p=project;engine.project=p;render();let imported=0;try{for(const f of files){notify(`Importando ${imported+1}/${files.length} · ${f.name}`);try{const b=await engine.decode(f),tid=id(),peaks=Array.from({length:400},(_,i)=>{const a=b.getChannelData(0),start=Math.floor(i*a.length/400),end=Math.floor((i+1)*a.length/400);let max=0;for(let j=start;j<end;j+=Math.max(1,Math.floor((end-start)/128)))max=Math.max(max,Math.abs(a[j]));return max;});await DB.putAudio(tid,f);p.tracks.push({id:tid,name:f.name.replace(/\.[^.]+$/,''),duration:b.duration,db:0,pan:0,mute:false,solo:false,speed:100,pitch:0,route:'master',peaks});p.speedTracks?.push(tid);imported++;await DB.saveProject(p);}catch(error){console.error(error);notify(`Não foi possível importar ${f.name}. Confira o formato e o espaço disponível.`);}}}finally{loading=false;await choose(p);notify(`${imported} de ${files.length} tracks importadas.`);navigator.storage?.persist?.().catch(()=>{});}};
$('#backupFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{notify('Restaurando backup…');const project=await DB.importBackup(file);projects.push(project);await choose(project);}catch(err){fail(err);}};
function editProject(){show(head('Editar projeto')+`<div class="stack"><label>Nome<input id="projectName" value="${esc(p.name)}"></label><label>Tom<input id="projectKey" value="${esc(p.key)}" placeholder="Ex.: E ou F#"></label><label>Imagem do projeto<input id="artwork" type="file" accept="image/*"></label><button id="clearArt">Remover imagem</button><button id="addTracks">Adicionar tracks</button><p class="muted">Ordem das tracks</p>${p.tracks.map((t,i)=>`<div class="row"><span class="spacer">${esc(t.name)}</span><button data-up="${i}" aria-label="Subir ${esc(t.name)}">↑</button><button data-down="${i}" aria-label="Descer ${esc(t.name)}">↓</button></div>`).join('')}<div class="actions"><button id="deleteProject" class="danger">Excluir projeto</button><button id="saveEdit" class="primary">Salvar</button></div></div>`);let art=p.art;$('#artwork').onchange=async e=>{const file=e.target.files[0];if(!file)return;const url=URL.createObjectURL(file),img=new Image();try{img.src=url;await img.decode();const c=document.createElement('canvas');c.width=640;c.height=360;c.getContext('2d').drawImage(img,0,0,640,360);art=c.toDataURL('image/jpeg',.8);}finally{URL.revokeObjectURL(url);}};$('#clearArt').onclick=()=>{art=null;notify('Imagem será removida ao salvar.');};$('#saveEdit').onclick=()=>{p.name=$('#projectName').value.trim()||p.name;p.key=$('#projectKey').value.trim();p.art=art;persist();modal.close();render();};$('#addTracks').onclick=()=>{modal.close();startImport(p);};listen('[data-up],[data-down]','click',(_,el)=>{const up=el.dataset.up!==undefined,i=+(up?el.dataset.up:el.dataset.down),j=i+(up?-1:1);if(j>=0&&j<p.tracks.length){[p.tracks[i],p.tracks[j]]=[p.tracks[j],p.tracks[i]];persist();editProject();}});$('#deleteProject').onclick=async()=>{if(!confirm(`Excluir ${p.name} e as cópias de áudio deste navegador? Os arquivos originais permanecem intactos.`))return;engine.stop();await DB.deleteProject(p);projects=projects.filter(x=>x!==p);p=null;engine.project=null;modal.close();render();};}
$('#search').onclick=()=>{show(head('Pesquisar projetos')+'<input id="query" aria-label="Nome ou tom" placeholder="Nome do projeto ou tom, como F#"><div class="search-results" id="results"></div>');const run=()=>{const q=$('#query').value.toLocaleLowerCase();$('#results').innerHTML=projects.filter(x=>x.name.toLocaleLowerCase().includes(q)||x.key.toLocaleLowerCase().includes(q)).map(x=>`<button data-result="${x.id}">${esc(x.name)} <small>· ${esc(x.key||'Sem tom')}</small></button>`).join('')||'<p>Nenhum projeto encontrado.</p>';listen('[data-result]','click',(_,el)=>{modal.close();choose(projects.find(x=>x.id===el.dataset.result));});};$('#query').oninput=run;run();$('#query').focus();};
$('#menu').onclick=()=>{show(`<div class="drawer-main"><button data-close class="close">Fechar</button><img src="assets/logo.png" alt="Logo ATMyTrack"><h2>ATMyTrack</h2><button data-nav="projects">▦　Projetos</button><button data-nav="tuner">♫　Afinador</button></div><div class="bottom"><button data-nav="support">◇　DEIXE SUA MARCA</button><button data-nav="help">?　Central de dúvidas</button></div>`,true);listen('[data-nav]','click',(_,el)=>navigate(el.dataset.nav));};
function navigate(next){window.scrollTo(0,0);modal.close();tuner.stop();if(next==='tuner')engine.pause();screen=next;history.pushState({screen:next},'',next==='projects'?'#projetos':'#'+next);render();}
addEventListener('popstate',e=>{window.scrollTo(0,0);tuner.stop();screen=e.state?.screen||'projects';render();});

function dsp(kind){const speed=kind==='speed',title=speed?'VELOCIDADE':'TOM',value=speed?p.speed:p.pitch,selected=new Set((speed?p.speedTracks:p.pitchTracks)??p.tracks.map(t=>t.id));show(head(title)+`<div class="large-value" id="dspValue">${value}${speed?'%':''}</div><input id="dspSlider" aria-label="${title}" type="range" style="width:100%" min="${speed?50:-12}" max="${speed?200:12}" step="1" value="${value}"><div class="row between"><button id="minus">−</button><span>${speed?'50% a 200% · tom preservado':'−12 a +12 semitons'}</span><button id="plus">＋</button></div><div class="presets">${(speed?[50,75,80,90,100,110,125,150,200]:[-12,-5,-2,-1,0,1,2,5,12]).map(v=>`<button data-preset="${v}">${v===(speed?100:0)?'Original':v+(speed?'%':'')}</button>`).join('')}</div><p class="footer">${speed?'Todas as tracks é o modo recomendado para preservar sincronização.':'Seleção independente da velocidade.'}</p><div class="row"><button id="allTracks">Selecionar todas</button><button id="noTracks">Limpar seleção</button></div><div class="track-list">${p.tracks.map(t=>`<label class="check"><input type="checkbox" data-select="${t.id}" ${selected.has(t.id)?'checked':''}>${esc(t.name)}</label>`).join('')}</div><div class="actions"><button id="resetDsp">${speed?'Reset 100%':'Tom original'}</button><button id="applyDsp" class="primary">Aplicar</button></div>`);
  const update=v=>{$('#dspSlider').value=v;$('#dspValue').textContent=$('#dspSlider').value+(speed?'%':'');};$('#dspSlider').oninput=e=>update(e.target.value);$('#minus').onclick=()=>update(+$ ('#dspSlider').value-1);$('#plus').onclick=()=>update(+$ ('#dspSlider').value+1);listen('[data-preset]','click',(_,el)=>update(el.dataset.preset));$('#allTracks').onclick=()=>document.querySelectorAll('[data-select]').forEach(x=>x.checked=true);$('#noTracks').onclick=()=>document.querySelectorAll('[data-select]').forEach(x=>x.checked=false);
  const apply=async v=>{const ids=[...document.querySelectorAll('[data-select]:checked')].map(x=>x.dataset.select);if(speed&&v!==100&&ids.length&&ids.length!==p.tracks.length&&!confirm('Tracks com velocidades diferentes podem perder sincronização entre si. Continuar?'))return;const playing=engine.playing,oldRate=globalRate(p),musical=engine.current()*oldRate;engine.pause();p[kind]=v;p[kind+'Tracks']=ids;for(const t of p.tracks){if(speed)t.speed=ids.includes(t.id)?v:100;else t.pitch=ids.includes(t.id)?v:0;}engine.position=musical/globalRate(p);persist();modal.close();render();if(playing){notify('Preparando processamento…');await engine.play();render();}};$('#applyDsp').onclick=()=>apply(+$('#dspSlider').value).catch(fail);$('#resetDsp').onclick=()=>apply(speed?100:0).catch(fail);
}
function metronome(){show(head('Metrônomo')+`<div class="stack"><div class="row"><button id="tap" class="primary">TAP</button><label class="check"><input id="smart" type="checkbox" ${p.smart?'checked':''}>Smart Click</label></div><p id="smartInfo">Original: ${p.bpm} BPM · Atual: ${(p.bpm*globalRate(p)).toFixed(1)} BPM</p><label>BPM original<input id="bpm" type="number" min="20" max="300" step=".1" value="${p.bpm}"></label><div class="row"><label class="spacer">Compasso<select id="meter">${[2,3,4,5,6,7,8,12].map(n=>`<option ${n===p.meter?'selected':''}>${n}</option>`).join('')}</select></label><label class="spacer">Divisão<select id="division">${[.5,1,2].map(n=>`<option value="${n}" ${n===p.clickDivision?'selected':''}>${n}x</option>`).join('')}</select></label></div><label>Timbre<select id="tone">${['Click','Madeira','Agudo','Bloco','Digital','Grave','Ping'].map((n,i)=>`<option value="${i}" ${i===p.clickTone?'selected':''}>${n}</option>`).join('')}</select></label><label>Volume<input id="clickDb" type="range" min="-60" max="0" step="1" value="${p.clickDb}"></label><label class="check"><input id="accent" type="checkbox" ${p.clickAccent?'checked':''}>Acentuar primeira batida</label><p>0.5x / 1x / 2x alteram somente o click. Para alterar a música, use Velocidade.</p></div><div class="actions"><button id="clickPlay" class="primary">${p.click?'Pausar click':'Play'}</button><button id="closeMetro">Fechar</button></div>`);
  const save=()=>{p.bpm=Math.max(20,Math.min(300,+$('#bpm').value||72));p.meter=+$('#meter').value;p.clickDivision=+$('#division').value;p.clickDb=+$('#clickDb').value;p.clickTone=+$('#tone').value;p.clickAccent=$('#accent').checked;persist();};listen('#bpm,#meter,#division,#clickDb,#tone,#accent','change',async()=>{save();await engine.rebuild();});$('#tap').onclick=()=>{const now=performance.now();if(taps.length&&now-taps.at(-1)>2500)taps=[];taps.push(now);if(taps.length>6)taps.shift();if(taps.length>1){$('#bpm').value=Math.round(60000*(taps.length-1)/(taps.at(-1)-taps[0]));save();engine.rebuild().catch(fail);}};
  $('#smart').onchange=()=>{p.smart=$('#smart').checked;persist();if(!p.smart)return;const t=p.tracks.find(t=>/click|clk|metro/i.test(t.name))||p.tracks.find(t=>/drum|bateria|perc/i.test(t.name))||p.tracks[0],b=engine.buffers.get(t?.id);if(!b)return;$('#smartInfo').textContent='Analisando pulsação…';const worker=new Worker(new URL('./analysis-worker.js',import.meta.url),{type:'module'}),samples=b.getChannelData(0).slice(0,b.sampleRate*120),project=p;worker.onmessage=({data})=>{worker.terminate();if(p!==project||!p.smart)return;if(data.bpm){p.bpm=data.bpm;persist();if($('#bpm')){$('#bpm').value=p.bpm;$('#smartInfo').textContent=`Original: ${p.bpm} BPM · Atual: ${(p.bpm*globalRate(p)).toFixed(1)} BPM. Confira metade/dobro.`;}engine.rebuild().catch(fail);}else if($('#smartInfo'))$('#smartInfo').textContent='Pulsação não identificada com confiança. Use TAP.';};worker.postMessage({type:'tempo',samples,rate:b.sampleRate},[samples.buffer]);};
  $('#clickPlay').onclick=async()=>{save();p.click=!p.click;persist();if(engine.playing)await engine.rebuild();else if(p.click)await engine.play();$('#clickPlay').textContent=p.click?'Pausar click':'Play';};$('#closeMetro').onclick=()=>{save();modal.close();render();};
}
function sections(){const originalDuration=Math.max(0,...p.tracks.map(t=>t.duration)),pos=engine.current()*globalRate(p);show(head('Seções')+`<p>Posição musical: <b id="sectionTime">${time(pos)}</b></p><canvas id="sectionWave" class="wave"></canvas><input id="sectionSeek" aria-label="Navegar na música" type="range" min="0" max="${originalDuration}" step=".01" value="${pos}" style="width:100%"><div class="stack"><label>Nome<input id="markerName" placeholder="Refrão"></label><div class="row"><label class="spacer">Início (segundos)<input id="markerStart" type="number" min="0" step=".01" value="${pos.toFixed(2)}"></label><label class="spacer">Fim (segundos)<input id="markerEnd" type="number" min="0" step=".01" value="${Math.min(originalDuration,pos+10).toFixed(2)}"></label></div><div class="row"><button id="markStart">Usar posição no início</button><button id="markEnd">Usar posição no fim</button></div><button id="addMarker" class="primary">Salvar seção</button>${p.markers.map(m=>`<div class="row"><span class="spacer">${esc(m.name)} · ${time(m.start)}–${time(m.end)}</span><button data-select-marker="${m.id}">Selecionar loop</button><button data-remove-marker="${m.id}" aria-label="Excluir seção ${esc(m.name)}">×</button></div>`).join('')}</div>`);const c=$('#sectionWave');c.width=540;c.height=90;const ctx=c.getContext('2d');ctx.strokeStyle='#86b1ff';(p.tracks[0]?.peaks||[]).forEach((v,i)=>{ctx.beginPath();ctx.moveTo(i*540/400,45-v*40);ctx.lineTo(i*540/400,45+v*40);ctx.stroke();});$('#sectionSeek').oninput=e=>{$('#sectionTime').textContent=time(+e.target.value);};$('#sectionSeek').onchange=e=>engine.seek(+e.target.value/globalRate(p)).catch(fail);$('#markStart').onclick=()=>$('#markerStart').value=(engine.current()*globalRate(p)).toFixed(2);$('#markEnd').onclick=()=>$('#markerEnd').value=(engine.current()*globalRate(p)).toFixed(2);$('#addMarker').onclick=()=>{const start=+$('#markerStart').value,end=+$('#markerEnd').value;if(!(end>start&&start>=0&&end<=originalDuration+.01)){notify('O fim deve vir após o início e ficar dentro da música.');return;}p.markers.push({id:id(),name:$('#markerName').value.trim()||'Seção',start,end});persist();sections();render();};listen('[data-select-marker]','click',async(_,el)=>{p.selectedMarker=el.dataset.selectMarker;persist();await engine.rebuild();modal.close();render();});listen('[data-remove-marker]','click',async(_,el)=>{p.markers=p.markers.filter(m=>m.id!==el.dataset.removeMarker);if(p.selectedMarker===el.dataset.removeMarker)p.selectedMarker=null;persist();await engine.rebuild();sections();render();});}
function groups(){show(head('DCA / BUS')+`<div class="row"><button id="newDca">＋ DCA</button><button id="newBus">＋ BUS</button></div><div class="stack">${['dcas','buses'].map(type=>p[type].map(g=>`<section class="panel group"><div class="row"><h3 class="spacer">${type==='dcas'?'DCA':'BUS'} · ${esc(g.name)}</h3><button data-remove-group="${type}:${g.id}">Excluir</button></div><label>Volume · <span id="group-value-${g.id}">${g.db} dB</span><input style="width:100%" type="range" min="-60" max="10" step=".1" value="${g.db}" data-group-gain="${type}:${g.id}"></label><label class="check"><input type="checkbox" data-group-mute="${type}:${g.id}" ${g.mute?'checked':''}>Mute</label>${type==='dcas'?p.tracks.map(t=>`<label class="check"><input data-member="${g.id}:${t.id}" type="checkbox" ${g.members.includes(t.id)?'checked':''}>${esc(t.name)}</label>`).join(''):'<p>Envie tracks para este BUS no Routing.</p>'}</section>`).join('')).join('')}</div>`);const create=type=>{const name=prompt(type==='dcas'?'Nome do DCA':'Nome do BUS');if(!name?.trim())return;p[type].push({id:id(),name:name.trim(),db:0,mute:false,members:[],route:'master'});persist();groups();engine.rebuild().catch(fail);};$('#newDca').onclick=()=>create('dcas');$('#newBus').onclick=()=>create('buses');listen('[data-group-gain]','input',(_,el)=>{const [type,tid]=el.dataset.groupGain.split(':'),g=p[type].find(x=>x.id===tid);g.db=+el.value;$(`#group-value-${tid}`).textContent=g.db.toFixed(1)+' dB';engine.updateMix();persist();});listen('[data-group-mute]','change',(_,el)=>{const [type,tid]=el.dataset.groupMute.split(':');p[type].find(x=>x.id===tid).mute=el.checked;engine.updateMix();persist();});listen('[data-member]','change',(_,el)=>{const [d,t]=el.dataset.member.split(':'),group=p.dcas.find(x=>x.id===d);group.members=el.checked?[...new Set([...group.members,t])]:group.members.filter(x=>x!==t);engine.updateMix();persist();});listen('[data-remove-group]','click',async(_,el)=>{const [type,tid]=el.dataset.removeGroup.split(':');p[type]=p[type].filter(x=>x.id!==tid);for(const t of p.tracks)if(t.route===tid)t.route='master';persist();await engine.rebuild();groups();});}
function routing(){const opts=route=>[['master','MASTER · estéreo'],['left','OUT 1/2 · esquerda'],['right','OUT 2/2 · direita']].map(([v,n])=>`<option value="${v}" ${v===route?'selected':''}>${n}</option>`).join('');show(head('Routing')+`<p>A versão web usa a saída estéreo disponibilizada pelo navegador. Interfaces com saídas adicionais ainda não são suportadas.</p><div class="stack">${p.tracks.map(t=>`<label>${esc(t.name)}<select data-route="${t.id}">${opts(t.route)}${p.buses.map(b=>`<option value="${b.id}" ${b.id===t.route?'selected':''}>BUS · ${esc(b.name)}</option>`).join('')}</select></label>`).join('')}${p.buses.map(b=>`<label>BUS · ${esc(b.name)}<select data-bus-route="${b.id}">${opts(b.route)}</select></label>`).join('')}<label>Click interno<select id="clickRoute">${opts(p.clickRoute)}</select></label><button id="split">Stereo split · Click/Guide à esquerda</button></div>`);listen('[data-route]','change',async(_,el)=>{p.tracks.find(t=>t.id===el.dataset.route).route=el.value;persist();await engine.rebuild();});listen('[data-bus-route]','change',async(_,el)=>{p.buses.find(b=>b.id===el.dataset.busRoute).route=el.value;persist();await engine.rebuild();});$('#clickRoute').onchange=async e=>{p.clickRoute=e.target.value;persist();await engine.rebuild();};$('#split').onclick=async()=>{for(const t of p.tracks)t.route=/click|guide|guia|clk/i.test(t.name)?'left':'right';p.clickRoute='left';persist();await engine.rebuild();routing();};}

function renderTuner(){const pref=tunerPrefs,inst=instruments[pref.instrument]||instruments[1],tunings=inst[1],notes=tunings[pref.tuning]?.[1]||[];app.innerHTML=`<section class="tuner"><div class="row between"><h1>Afinador</h1><button id="back">Voltar aos projetos</button></div><p>Análise local pelo microfone. O player permanece pausado.</p><div class="panel tuner-grid"><div class="stack tuner-controls"><label>Instrumento<select id="instrument">${instruments.map(([name],i)=>`<option value="${i}" ${i===pref.instrument?'selected':''}>${name}</option>`).join('')}</select></label>${notes.length?`<label>Afinação<select id="tuning">${tunings.map(([name],i)=>`<option value="${i}" ${i===pref.tuning?'selected':''}>${name}</option>`).join('')}</select></label><label>Corda<select id="string"><option value="-1">AUTO</option>${notes.map((n,i)=>`<option value="${i}" ${i===pref.string?'selected':''}>${notes.length-i}ª · ${noteName(n)}</option>`).join('')}</select></label>`:''}<label>Referência A4 (Hz)<input id="a4" type="number" min="400" max="480" value="${pref.a4}"></label><button id="resetA4">Reset 440 Hz</button><label>MIC<progress id="mic" value="0" max="1"></progress></label><button id="micStart" class="primary">Permitir microfone</button></div><div class="tuner-reading" id="reading"><div class="note" id="note">—</div><p class="frequency" id="freq">AGUARDANDO SINAL</p><p id="target">Toque uma corda</p><div class="gauge"><span class="needle" id="needle"></span></div><div class="gauge-labels"><span>−50</span><span>−25</span><span>0</span><span>+25</span><span>+50</span></div><div class="cents" id="cents">— cents</div><p class="direction" id="direction">O microfone é usado somente nesta tela.</p></div></div></section>`;
  $('#back').onclick=()=>navigate('projects');const save=()=>localStorage.setItem('tuner',JSON.stringify(pref));$('#instrument').onchange=e=>{pref.instrument=+e.target.value;pref.tuning=0;pref.string=-1;save();tuner.stop();renderTuner();};if($('#tuning'))$('#tuning').onchange=e=>{pref.tuning=+e.target.value;pref.string=-1;save();tuner.stop();renderTuner();};if($('#string'))$('#string').onchange=e=>{pref.string=+e.target.value;save();};$('#a4').onchange=e=>{pref.a4=Math.max(400,Math.min(480,+e.target.value||440));e.target.value=pref.a4;save();};$('#resetA4').onclick=()=>{pref.a4=440;$('#a4').value=440;save();};
  $('#micStart').onclick=async()=>{try{$('#micStart').disabled=true;await tuner.start(r=>{if(screen!=='tuner'||!$('#note'))return;$('#mic').value=Math.min(1,r.rms*8);if(r.error){$('#direction').textContent='Falha na análise. Ative o microfone novamente.';$('#micStart').disabled=false;return;}if(!r.frequency){$('#note').textContent='—';$('#freq').textContent='AGUARDANDO SINAL ESTÁVEL';$('#cents').textContent='— cents';$('#target').textContent='Toque uma corda';$('#direction').textContent='AGUARDANDO SINAL ESTÁVEL';$('#needle').style.left='50%';$('#reading').classList.remove('tuned');return;}const d=tunerReading(r.frequency,notes,pref.string,pref.a4),delta=d.targetCents??d.cents,tuned=Math.abs(delta)<=3;$('#note').textContent=noteName(d.midi);$('#freq').textContent=r.frequency.toFixed(2)+' Hz';$('#cents').textContent=`${d.cents>=0?'+':''}${d.cents.toFixed(1)} cents · nota captada`;$('#target').textContent=d.target===null?'Modo cromático':`Alvo: ${notes.length-notes.indexOf(d.target)}ª corda · ${noteName(d.target)} · ${delta>=0?'+':''}${delta.toFixed(1)} cents` ;$('#needle').style.left=(50+Math.max(-50,Math.min(50,d.cents)))+'%';$('#reading').classList.toggle('tuned',tuned);$('#direction').textContent=tuned?'AFINADO':delta<0?'↑ AUMENTE A AFINAÇÃO':'↓ DIMINUA A AFINAÇÃO';});if($('#micStart')){$('#micStart').textContent='Microfone ativo';$('#micStart').disabled=false;}}catch(e){console.error(e);if($('#micStart')){$('#micStart').disabled=false;$('#direction').textContent='Permita o microfone nas configurações do site e tente novamente. É necessário HTTPS.';}}};
}
document.addEventListener('visibilitychange',()=>{if(document.hidden){tuner.stop();if(screen==='tuner'&&$('#micStart'))$('#micStart').textContent='Retomar microfone';}});
const pix='00020126660014BR.GOV.BCB.PIX0111411120718900229Faça parte do mundo ATMyTrack5204000053039865802BR5917Andre Souza Teles6009SAO PAULO62140510qERAMLYJ726304C2A9';
function renderSupport(){app.innerHTML=`<div class="row between"><h1>Deixe sua marca</h1><button id="back">Voltar aos projetos</button></div><div class="panel" style="max-width:850px;margin:auto"><h2>Seu nome no mundo ATMyTrack</h2><p>Contribuições acima de R$ 10 permitem incluir seu nome no globo. A confirmação do Pix e a inclusão são feitas manualmente pelo responsável.</p><input id="findName" placeholder="Pesquisar nome no globo" aria-label="Pesquisar nome no globo"><canvas class="globe" id="globe"></canvas><p class="muted" id="globeLabel">Nomes de demonstração são fictícios e não representam pagamentos.</p><label>Nome completo<input id="supportName" autocomplete="name" value="${esc(localStorage.getItem('supportName')||'')}"></label><div class="actions"><button id="shareName">Compartilhar identificação</button></div><img class="qr" src="assets/pix.jpg" alt="QR Code Pix ATMyTrack"><div class="row"><a href="https://nubank.com.br/cobrar/53y8j/6ac5cae5-bc5f-4067-ada8-1154e541b67a" target="_blank" rel="noopener noreferrer">Abrir pagamento Nubank</a><button id="copyPix">Copiar Pix</button></div><p class="footer">A contribuição não é verificada automaticamente. O formulário não envia seu nome a um servidor; compartilhe a identificação pelo canal combinado.</p></div>`;$('#back').onclick=()=>navigate('projects');$('#supportName').onchange=e=>localStorage.setItem('supportName',e.target.value);$('#copyPix').onclick=()=>navigator.clipboard.writeText(pix).then(()=>notify('Pix copiado.')).catch(fail);$('#shareName').onclick=async()=>{const text=`ATMyTrack — solicitação de inclusão no globo: ${$('#supportName').value.trim()}`;localStorage.setItem('supportName',$('#supportName').value);try{if(navigator.share)await navigator.share({text});else{await navigator.clipboard.writeText(text);notify('Identificação copiada.');}}catch(e){if(e.name!=='AbortError')fail(e);}};drawGlobe();}
async function drawGlobe(){const people=await fetch('assets/supporters.json').then(r=>r.json());if(!$('#globe'))return;const c=$('#globe'),ctx=c.getContext('2d');let yaw=0,pitch=0,drag=null,paused=false,focus='';const points=people.map((p,i)=>{const y=1-2*(i+.5)/people.length,r=Math.sqrt(1-y*y),phi=i*Math.PI*(3-Math.sqrt(5));return {...p,x:Math.cos(phi)*r,y,z:Math.sin(phi)*r};});c.onpointerdown=e=>{drag=[e.clientX,e.clientY];paused=true;c.setPointerCapture(e.pointerId);};c.onpointermove=e=>{if(!drag)return;yaw+=(e.clientX-drag[0])*.008;pitch+=(e.clientY-drag[1])*.008;drag=[e.clientX,e.clientY];};c.onpointerup=()=>{drag=null;};$('#findName').oninput=e=>{const person=points.find(p=>p.name.toLowerCase().includes(e.target.value.toLowerCase()));paused=!!e.target.value;focus=person?.name||'';if(paused&&person){yaw=-Math.atan2(person.x,person.z);pitch=Math.atan2(person.y,Math.sqrt(person.x**2+person.z**2));$('#globeLabel').textContent=person.name+(person.demo?' · demonstração fictícia':'');}};const tick=()=>{if(screen!=='support'||!c.isConnected)return;const width=c.clientWidth;c.width=width*devicePixelRatio;c.height=340*devicePixelRatio;ctx.scale(devicePixelRatio,devicePixelRatio);ctx.clearRect(0,0,width,340);if(!paused)yaw+=.002;const radius=Math.min(width*.37,135);ctx.strokeStyle='#243e65';ctx.lineWidth=1;ctx.beginPath();ctx.arc(width/2,170,radius,0,Math.PI*2);ctx.stroke();points.map(p=>{const x=p.x*Math.cos(yaw)+p.z*Math.sin(yaw),z=p.z*Math.cos(yaw)-p.x*Math.sin(yaw),y=p.y*Math.cos(pitch)-z*Math.sin(pitch),depth=z*Math.cos(pitch)+p.y*Math.sin(pitch);return {...p,px:width/2+x*radius,py:170+y*radius,depth};}).sort((a,b)=>a.depth-b.depth).forEach(p=>{ctx.globalAlpha=.3+.7*(p.depth+1)/2;ctx.fillStyle=p.name===focus?'#edf3ff':'#86b1ff';ctx.font=`${12+(p.depth+1)*2}px Segoe UI`;ctx.textAlign='center';ctx.fillText(p.name,p.px,p.py);});ctx.globalAlpha=1;requestAnimationFrame(tick);};tick();}
function renderHelp(){app.innerHTML=`<div class="row between"><h1>Central de dúvidas</h1><button id="back">Voltar aos projetos</button></div><section class="panel stack" style="max-width:900px"><h2>Preparar e tocar</h2><p>Importe as tracks de uma música em um projeto. Os formatos disponíveis dependem do navegador (WAV e MP3 são boas opções). Play usa um único relógio para todas as tracks. Navegar pelo menu não reinicia a música.</p><h3>Mixer, DCA e BUS</h3><p>Faders começam em 0 dB. O botão 0dB retorna ao volume original. Pan, Mute e Solo são independentes. Arraste o nome de uma track para reorganizar o canal. DCA controla ganhos de um grupo; BUS soma tracks e permite encaminhar o grupo. Routing e Stereo split oferecem esquerda, direita e estéreo da saída do navegador.</p><h3>Tom e velocidade</h3><p>Tom altera semitons; Velocidade altera duração preservando o pitch. Seleções independentes e reset. Em 100% com tom original, o DSP é ignorado. Todas as tracks na mesma velocidade acompanham o BPM e o click. Seleções diferentes podem perder sincronização. Mudanças durante Play fazem uma pequena preparação e retomam a posição musical.</p><h3>Seções e loop</h3><p>Crie início/fim na timeline original. Toque na seção para navegar, segure para selecioná-la e ative Loop. Sem seção selecionada, Loop repete o projeto. As posições são convertidas conforme a velocidade.</p><h3>Metrônomo</h3><p>TAP define o BPM por toques. Smart Click estima a pulsação de Click/Drums: confira metade/dobro. A divisão 0.5x/1x/2x afeta somente o click. Play no painel ativa o click e inicia a música.</p><h3>Afinador</h3><p>Permita o microfone quando solicitado. A nota grande é sempre a nota captada, com sustenido quando aplicável. A corda-alvo aparece separadamente. AUTO sugere a corda mais próxima; se estiver muito desafinada, selecione manualmente. Azul indica ±3 cents do alvo. A4 padrão 440 Hz. O microfone é encerrado ao sair ou ocultar a página.</p><h3>Seus arquivos</h3><p>Áudio e projetos ficam apenas neste navegador, sem conta ou envio ao servidor. Exporte um backup regularmente; limpar dados do site pode apagar a biblioteca. O backup web pode ser importado em outro navegador. Projetos Android não são importados automaticamente.</p><h3>Limites da versão web</h3><p>Mantenha a página aberta e a tela ativa. Suspensão em segundo plano e limites de memória variam por navegador. A versão web carrega áudio decodificado na memória, com limite de 384 MB por projeto. Interfaces USB com mais de dois canais e paridade de performance com o Android não são garantidas. Teste seu aparelho antes de usar ao vivo.</p><p><a href="vendor/Signalsmith-LICENSE.txt">Signalsmith Stretch · licença MIT</a></p></section>`;$('#back').onclick=()=>navigate('projects');}
setInterval(()=>{if(screen==='projects'&&p){if($('#clock'))$('#clock').textContent=time(engine.current())+' / '+time(duration(p));if($('#play')){$('#play').textContent=engine.busy?'Preparando…':engine.playing?'Ⅱ Pausar':'▶ Play';$('#play').disabled=loading||engine.busy||!engine.ready;}drawWave();for(const [tid,peak]of engine.meters()){const el=$('#meter-'+tid);if(el){el.style.height=Math.min(100,peak*100)+'%';el.style.background=peak>=1?'#ef6262':peak>.8?'#efb65e':'#387bff';}}}},80);
try{projects=await DB.allProjects();if(projects.length)await choose(projects[0]);else render();}catch(e){render();fail(e);}
